// frontend/src/components/Dashboard.js
import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import AppShell from './AppShell';
import { getHistory } from '../services/api';

const DAILY_WATER_INCREMENT = 0.25;
const WEEK_DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export default function Dashboard() {
  const navigate = useNavigate();
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [todayWater, setTodayWater] = useState(() =>
    Number(localStorage.getItem('healthyme_today_water') || 0)
  );

  const storedUser = localStorage.getItem('user');
  const user = storedUser ? JSON.parse(storedUser) : null;
  const profile = user?.profile || {};

  useEffect(() => {
    localStorage.setItem('healthyme_today_water', String(todayWater));
  }, [todayWater]);

  useEffect(() => {
    let isMounted = true;

    const fetchHistory = async () => {
      setLoading(true);
      setError('');

      try {
        const response = await getHistory();
        if (isMounted) {
          setHistory(Array.isArray(response) ? response : []);
        }
      } catch (fetchError) {
        if (fetchError.message === 'Missing authentication token') {
          navigate('/login');
          return;
        }
        if (isMounted) {
          setError(fetchError.message || 'Failed to fetch data');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    fetchHistory();

    return () => {
      isMounted = false;
    };
  }, [navigate]);

  const summary = useMemo(() => {
    const latest = history[0];

    const average = (key) =>
      history.length
        ? history.reduce((sum, item) => sum + Number(item.input_data?.[key] || 0), 0) / history.length
        : 0;

    const weeklyEntries = history.filter((item) => {
      const created = new Date(item.created_at);
      return Date.now() - created.getTime() <= 7 * 24 * 60 * 60 * 1000;
    });

    const waterGoal = Number(profile.daily_water_goal || 3);
    const averageWater = average('water');
    const averageCalories = average('calories');
    const latestScore = latest ? Number(latest.score) : null;

    return {
      latestScore,
      latestScoreLabel: latestScore === null ? '--' : latestScore.toFixed(1),
      averageSleepLabel: average('sleep') ? `${average('sleep').toFixed(1)}h` : '0h',
      averageWaterLabel: averageWater ? `${averageWater.toFixed(1)}L` : '0L',
      averageCaloriesLabel: averageCalories ? `${Math.round(averageCalories)}` : '0',
      averageCalories,
      streakDays: new Set(
        weeklyEntries.map((item) => new Date(item.created_at).toDateString())
      ).size,
      weeklyPredictionCount: weeklyEntries.length,
      waterGoal,
      calorieGoal:
        profile.goal === 'Gain Muscle' ? 2600 : profile.goal === 'Lose Weight' ? 1900 : 2200,
    };
  }, [history, profile.daily_water_goal, profile.goal]);

  const weeklyChart = useMemo(() => {
    const recent = [...history]
      .slice(0, 7)
      .reverse()
      .map((item) => ({
        day: new Date(item.created_at).toLocaleDateString('en-US', { weekday: 'short' }),
        score: Math.max(0, Math.min(100, Number(item.score) || 0)),
      }));

    return recent.length === 0
      ? WEEK_DAYS.map((day) => ({ day, score: 0 }))
      : recent;
  }, [history]);

  const streakCalendar = useMemo(() => {
    const activeDays = new Set(
      history
        .filter((item) => {
          const created = new Date(item.created_at);
          return Date.now() - created.getTime() <= 7 * 24 * 60 * 60 * 1000;
        })
        .map((item) => new Date(item.created_at).toLocaleDateString('en-US', { weekday: 'short' }))
    );

    return WEEK_DAYS.map((day) => ({
      day,
      active: activeDays.has(day),
    }));
  }, [history]);

  const mealCards = useMemo(() => {
    const source = profile.food_notes || '';
    const parts = source
      .split(/,|and/)
      .map((item) => item.trim())
      .filter(Boolean)
      .slice(0, 3);

    if (parts.length === 0) {
      return [
        { label: 'Breakfast', value: 'Protein-rich start', accent: 'orange' },
        { label: 'Lunch', value: 'Balanced whole-food meal', accent: 'teal' },
        { label: 'Dinner', value: 'Light recovery-focused plate', accent: 'purple' },
      ];
    }

    return [
      { label: 'Breakfast', value: parts[0] || 'Balanced breakfast', accent: 'orange' },
      { label: 'Lunch', value: parts[1] || parts[0] || 'Healthy lunch', accent: 'teal' },
      {
        label: 'Dinner',
        value: parts[2] || parts[parts.length - 1] || 'Light dinner',
        accent: 'purple',
      },
    ];
  }, [profile.food_notes]);

  const scoreMessage = useMemo(() => {
    if (summary.latestScore === null) {
      return 'Run your first prediction to unlock insights, meal guidance, and trend visuals.';
    }
    if (summary.latestScore >= 80) {
      return 'Excellent momentum. Keep sleep and hydration steady to protect your score.';
    }
    if (summary.latestScore >= 60) {
      return 'You are on track. A little more hydration and recovery can push you higher.';
    }
    if (summary.latestScore >= 40) {
      return 'Your routine can improve quickly with better rest, food balance, and water intake.';
    }
    return 'Start simple today: hydrate more, eat cleaner, and get better sleep tonight.';
  }, [summary.latestScore]);

  const waterProgress = Math.min(100, Math.round((todayWater / (summary.waterGoal || 1)) * 100));
  const calorieProgress = Math.min(
    100,
    Math.round((summary.averageCalories / (summary.calorieGoal || 1)) * 100)
  );
  const gaugeValue = summary.latestScore === null ? 0 : Math.round(summary.latestScore);

  const addWater = () => {
    setTodayWater((current) => Number((current + DAILY_WATER_INCREMENT).toFixed(2)));
  };

  const resetWater = () => {
    setTodayWater(0);
  };

  return (
    <AppShell
      title={`Welcome back, ${user?.name || 'User'}`}
      subtitle="A premium health dashboard with live hydration progress, ML score insights, streak tracking, meal cards, and weekly trend visuals."
    >
      {loading ? <div className="empty-state">Loading...</div> : null}
      {!loading && error ? <div className="empty-state">{error || 'Failed to fetch data'}</div> : null}

      {!loading && !error ? (
        <>
          <section className="dashboard-hero premium-dark">
            <div className="hero-score-panel premium-dark-panel">
              <span className="floating-blob blob-one" />
              <span className="floating-blob blob-two" />
              <div className="hero-illustration">AI</div>

              <div className="eyebrow">AI wellness score</div>

              <div className="hero-score-row">
                <div>
                  <h2>{summary.latestScoreLabel}</h2>
                  <p>{scoreMessage}</p>
                </div>

                <div className="hero-badge-stack">
                  <span className="hero-badge">Goal: {profile.goal || 'Stay Fit'}</span>
                  <span className="hero-badge soft">Streak: {summary.streakDays} days</span>
                </div>
              </div>

              <div className="hero-score-footer">
                <span>{summary.weeklyPredictionCount} predictions this week</span>
                <button
                  type="button"
                  className="ghost-btn ghost-invert"
                  onClick={() => navigate('/predict')}
                >
                  New prediction
                </button>
              </div>
            </div>

            <div className="hero-side-grid">
              <div className="spotlight-card water glass-panel">
                <span className="eyebrow">Hydration target</span>
                <strong>{summary.waterGoal}L</strong>
                <p>{profile.food_preference || 'Balanced'} nutrition plan</p>
              </div>

              <div className="spotlight-card food glass-panel">
                <span className="eyebrow">Food profile</span>
                <strong>{profile.food_preference || 'Balanced'}</strong>
                <p>
                  {profile.food_notes ||
                    'Add food notes during registration for a more personalized dashboard.'}
                </p>
              </div>
            </div>
          </section>

          <section className="wellness-grid">
            <div className="progress-card glass-panel">
              <div
                className="progress-ring"
                style={{ '--progress': `${waterProgress}%`, '--ring-color': '#20b8a6' }}
              >
                <div>
                  <strong>{waterProgress}%</strong>
                  <span>Water</span>
                </div>
              </div>

              <div className="progress-copy">
                <h3>Water intake tracker</h3>
                <p>
                  {todayWater.toFixed(2)}L logged today out of your {summary.waterGoal}L hydration
                  goal.
                </p>
                <div className="button-row">
                  <button type="button" className="primary-btn compact" onClick={addWater}>
                    + 250ml
                  </button>
                  <button type="button" className="ghost-btn compact" onClick={resetWater}>
                    Reset
                  </button>
                </div>
              </div>
            </div>

            <div className="progress-card glass-panel">
              <div
                className="progress-ring"
                style={{ '--progress': `${calorieProgress}%`, '--ring-color': '#ff9533' }}
              >
                <div>
                  <strong>{calorieProgress}%</strong>
                  <span>Calories</span>
                </div>
              </div>

              <div className="progress-copy">
                <h3>Food consumption trend</h3>
                <p>
                  Average calories: {summary.averageCaloriesLabel} / {summary.calorieGoal}. Goal
                  tuned for {profile.goal || 'general fitness'}.
                </p>
                <span className="hint">Track a new day in Predict to refresh this insight.</span>
              </div>
            </div>
          </section>

          <section className="dashboard-grid luxury">
            <div className="panel-card glass-panel gauge-panel">
              <div className="panel-head">
                <h3>Circular Score Gauge</h3>
                <span className="top-pill">Live score view</span>
              </div>

              <div className="gauge-layout">
                <div className="score-gauge" style={{ '--score-progress': gaugeValue }}>
                  <div className="score-gauge-inner">
                    <strong>{summary.latestScoreLabel}</strong>
                    <span>Health score</span>
                  </div>
                </div>

                <div className="gauge-copy">
                  <strong>
                    {gaugeValue >= 80
                      ? 'Excellent'
                      : gaugeValue >= 60
                        ? 'Strong'
                        : gaugeValue >= 40
                          ? 'Average'
                          : 'Needs care'}
                  </strong>
                  <p>
                    This gauge reflects your latest ML result from sleep, water, exercise, and
                    calories.
                  </p>
                </div>
              </div>
            </div>

            <div className="panel-card glass-panel">
              <div className="panel-head">
                <h3>Weekly Score Trend</h3>
                <span className="top-pill">Last 7 predictions</span>
              </div>

              <div className="weekly-chart">
                {weeklyChart.map((item, index) => (
                  <div className="chart-col" key={`${item.day}-${index}`}>
                    <div className="chart-track">
                      <div className="chart-bar" style={{ height: `${Math.max(item.score, 6)}%` }} />
                    </div>
                    <strong>{Math.round(item.score)}</strong>
                    <span>{item.day}</span>
                  </div>
                ))}
              </div>
            </div>
          </section>

          <section className="dashboard-grid luxury">
            <div className="panel-card glass-panel bottle-panel">
              <div className="panel-head">
                <h3>Water Bottle Tracker</h3>
                <span className="top-pill">{todayWater.toFixed(2)}L today</span>
              </div>

              <div className="bottle-wrap">
                <div className="water-bottle">
                  <div className="water-bottle-cap" />
                  <div className="water-bottle-body">
                    <div className="water-fill" style={{ height: `${Math.max(waterProgress, 4)}%` }}>
                      <span className="water-wave" />
                    </div>
                  </div>
                </div>

                <div className="bottle-copy">
                  <strong>{waterProgress}% of goal</strong>
                  <p>Keep tapping +250ml to simulate a live hydration tracker like a health app.</p>
                </div>
              </div>
            </div>

            <div className="panel-card glass-panel streak-panel">
              <div className="panel-head">
                <h3>Streak Calendar</h3>
                <span className="top-pill">{summary.streakDays} active days</span>
              </div>

              <div className="streak-calendar">
                {streakCalendar.map((entry) => (
                  <div key={entry.day} className={`streak-day ${entry.active ? 'active' : ''}`}>
                    <span>{entry.day}</span>
                    <strong>{entry.active ? '●' : '○'}</strong>
                  </div>
                ))}
              </div>
            </div>
          </section>

          <div className="stats-grid advanced">
            <div className="stat-card glass-panel">
              <div className="card-icon icon-orange">SC</div>
              <p className="stat-value">{summary.latestScoreLabel}</p>
              <div className="stat-label">Latest score</div>
            </div>

            <div className="stat-card glass-panel">
              <div className="card-icon icon-teal">SL</div>
              <p className="stat-value">{summary.averageSleepLabel}</p>
              <div className="stat-label">Avg. sleep</div>
            </div>

            <div className="stat-card glass-panel">
              <div className="card-icon icon-blue">WA</div>
              <p className="stat-value">{summary.averageWaterLabel}</p>
              <div className="stat-label">Avg. water</div>
            </div>

            <div className="stat-card glass-panel">
              <div className="card-icon icon-purple">CA</div>
              <p className="stat-value">{summary.averageCaloriesLabel}</p>
              <div className="stat-label">Avg. calories</div>
            </div>
          </div>

          <section className="panel-card glass-panel meal-section">
            <div className="panel-head">
              <h3>Meal Cards</h3>
              <span className="top-pill">{profile.food_preference || 'Balanced'} plan</span>
            </div>

            <div className="meal-grid">
              {mealCards.map((meal) => (
                <article key={meal.label} className={`meal-card ${meal.accent}`}>
                  <span className="meal-label">{meal.label}</span>
                  <strong>{meal.value}</strong>
                  <p>Food profile inspired by your onboarding details and daily eating pattern.</p>
                </article>
              ))}
            </div>
          </section>

          <section className="dashboard-grid luxury">
            <div className="panel-card feature-panel glass-panel">
              <div className="panel-head">
                <h3>Quick Actions</h3>
                <span className="top-pill">Personalized control center</span>
              </div>

              <div className="action-grid advanced">
                <button type="button" className="action-card premium" onClick={() => navigate('/predict')}>
                  <div className="card-icon icon-teal">PR</div>
                  <h3>Predict Score</h3>
                  <p>Run a fresh ML prediction from your sleep, water, exercise, and calories.</p>
                  <span className="card-arrow">Open</span>
                </button>

                <button type="button" className="action-card premium" onClick={() => navigate('/history')}>
                  <div className="card-icon icon-purple">HI</div>
                  <h3>View History</h3>
                  <p>See previous snapshots and compare patterns across your health routine.</p>
                  <span className="card-arrow">Open</span>
                </button>

                <button type="button" className="action-card premium" onClick={() => navigate('/chat')}>
                  <div className="card-icon icon-orange">AI</div>
                  <h3>Coach Chat</h3>
                  <p>Ask for daily advice about hydration, food, exercise, and better recovery.</p>
                  <span className="card-arrow">Open</span>
                </button>
              </div>
            </div>

            <div className="stack">
              <div className="panel-card insights-panel glass-panel">
                <div className="panel-head">
                  <h3>Daily Focus</h3>
                  <span className="top-pill">Smart suggestions</span>
                </div>

                <div className="insight-list">
                  <div className="insight-item">
                    <strong>Hydration</strong>
                    <span>
                      {waterProgress < 100
                        ? 'Drink one more glass before evening.'
                        : 'Great job hitting your water target.'}
                    </span>
                  </div>

                  <div className="insight-item">
                    <strong>Sleep</strong>
                    <span>
                      {summary.averageSleepLabel === '0h'
                        ? 'Add your first prediction to unlock sleep insights.'
                        : `Your recent average is ${summary.averageSleepLabel}.`}
                    </span>
                  </div>

                  <div className="insight-item">
                    <strong>Nutrition</strong>
                    <span>
                      {profile.food_preference || 'Balanced'} plan with{' '}
                      {profile.goal || 'fitness'} as the main goal.
                    </span>
                  </div>
                </div>
              </div>

              <div className="panel-card profile-panel glass-panel">
                <h3>Your Health Profile</h3>

                <div className="mini-grid">
                  <div className="mini-card">
                    <span className="hint">Goal</span>
                    <strong>{profile.goal || 'Stay Fit'}</strong>
                  </div>
                  <div className="mini-card">
                    <span className="hint">Activity</span>
                    <strong>{profile.activity_level || 'Moderate'}</strong>
                  </div>
                  <div className="mini-card">
                    <span className="hint">Height</span>
                    <strong>{profile.height || '--'} cm</strong>
                  </div>
                  <div className="mini-card">
                    <span className="hint">Weight</span>
                    <strong>{profile.weight || '--'} kg</strong>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </>
      ) : null}
    </AppShell>
  );
}
